mapper.select:
SELECT COUNT(*)
FROM CHAT_ROOM_MEMBER
WHERE ROOM_ID = #{roomId}
  AND USER_ID = #{userId}
  AND LEFT_AT IS NULL

mapper.update:
UPDATE CHAT_ROOM_MEMBER
SET LEFT_AT = #{leftAt}
WHERE ROOM_ID = #{roomId}
  AND USER_ID = #{userId}
  AND LEFT_AT IS NULL

UPDATE CHAT_ROOM_MEMBER
SET LAST_READ_MESSAGE_ID = GREATEST(NVL(LAST_READ_MESSAGE_ID, 0), #{messageId, jdbcType=NUMERIC})
WHERE ROOM_ID = #{roomId}
  AND USER_ID = #{userId}

UPDATE CHAT_ROOM
SET LAST_MESSAGE_AT = #{now},
    MOD_DT = #{now}
WHERE ROOM_ID = #{roomId}
